"""Regenerate js/data.js from data/smart_city_issues.csv.

Run from the project folder after editing the CSV:
    python tools/build_data_js.py
"""
import json
from pathlib import Path

root = Path(__file__).resolve().parent.parent
csv_text = (root / "data" / "smart_city_issues.csv").read_text(encoding="utf-8-sig")

js = (
    "/* ===== RESOLVE 360 - data.js =====\n"
    "   AUTO-GENERATED by tools/build_data_js.py from data/smart_city_issues.csv.\n"
    "   Used only when the page is opened directly from disk (file://). */\n"
    "window.EMBEDDED_CSV = " + json.dumps(csv_text) + ";\n"
)
(root / "js" / "data.js").write_text(js, encoding="utf-8")
print("Wrote js/data.js with", csv_text.count("\n") - 1, "data rows")
